```cpp
#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Define a regex pattern to match Markdown syntax
    std::regex pattern(R"(
        [^#]\*+\s*=\s*.*
        [^#]\s*=\s*.*
    )");
    // Replace all Markdown syntax with HTML
    std::string html = std::regex_replace(markdown, pattern, "<h>$1</h>$2");
    return html;
}

int main() {
    std::string markdown = "# Section\nThis is a section.\n\n## Subsection\nThis is a subheading.\n";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

